@import url("https://fonts.googleapis.com/css2?family=Italiana&family=DM+Sans:opsz,wght@9..40,400;9..40,500;9..40,700&display=swap");
:root{--esp:#2B1D16;--sand:#E8DFD3;--sand-2:#F4EFE8;--wine:#6E1E2C;--white:#fff;--text:#2F2621;--muted:#7A6D64;--line:#E4DCD2;
--serif:"Italiana",Didot,Georgia,serif;--sans:"DM Sans",system-ui,-apple-system,"Segoe UI",sans-serif;--wrap:1280px}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}
body{margin:0;font-family:var(--sans);font-size:16px;line-height:1.6;color:var(--text);background:#fff;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}a{color:inherit}p{margin:0 0 1em}
h1,h2,h3{font-family:var(--serif);font-weight:400;margin:0;line-height:1.05;color:var(--esp)}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 24px}
.skip{position:absolute;left:-999px}.skip:focus{left:12px;top:12px;background:var(--sand);padding:10px;z-index:99}
:focus-visible{outline:2px solid var(--wine);outline-offset:3px}
.ship{background:var(--esp);color:var(--sand);font-size:14px;text-align:center;padding:8px 16px}
.ship .t{max-width:320px;height:4px;background:#4A3A30;margin:6px auto 0;border-radius:2px;overflow:hidden}.ship .t i{display:block;height:100%;background:var(--sand);width:0;transition:width .3s}
.site-header{position:sticky;top:0;z-index:40;background:rgba(255,255,255,.96);border-bottom:1px solid var(--line)}
.nav{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;height:76px}
.menu{display:flex;gap:26px;list-style:none;margin:0;padding:0;font-size:15px}.menu a{text-decoration:none}.menu a:hover{color:var(--wine)}
.logo{font-family:var(--serif);font-size:34px;text-decoration:none;color:var(--esp);letter-spacing:.04em}
.icons{display:flex;justify-content:flex-end;gap:18px;align-items:center}
.icons button,.icons a{background:none;border:0;cursor:pointer;font:inherit;color:var(--esp);display:flex;align-items:center;gap:6px;text-decoration:none}
.bag-count{background:var(--esp);color:#fff;border-radius:999px;font-size:12px;min-width:20px;height:20px;display:inline-grid;place-items:center;padding:0 6px}
.burger{display:none}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:14px 28px;font-weight:500;text-decoration:none;border:1px solid var(--esp);font-family:var(--sans);font-size:15px;cursor:pointer;letter-spacing:.04em;transition:background .2s,color .2s}
.btn-dark{background:var(--esp);color:#fff}.btn-dark:hover{background:var(--wine);border-color:var(--wine)}
.btn-line{background:transparent;color:var(--esp)}.btn-line:hover{background:var(--esp);color:#fff}
.hero{display:grid;grid-template-columns:1fr 1fr;min-height:640px;background:var(--sand-2)}
.hero-copy{display:flex;flex-direction:column;justify-content:center;padding:60px 8% 60px max(24px,calc((100vw - 1280px)/2 + 24px))}
.hero .season{font-size:14px;letter-spacing:.2em;color:var(--muted);margin-bottom:18px}
.hero h1{font-size:clamp(52px,7vw,104px)}
.hero p{font-size:19px;color:var(--muted);max-width:40ch;margin:24px 0 30px}
.actions{display:flex;gap:12px;flex-wrap:wrap}
.hero-img{position:relative}.hero-img img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.perks{display:grid;grid-template-columns:repeat(4,1fr);border-bottom:1px solid var(--line)}
.perks div{padding:22px 24px;border-right:1px solid var(--line);font-size:14px}.perks div:last-child{border:0}.perks b{display:block;font-size:15px;color:var(--esp)}
section{padding:90px 0}
.head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:34px;flex-wrap:wrap}
.head h2{font-size:clamp(40px,5vw,64px)}
.chips{display:flex;gap:8px;flex-wrap:wrap}
.chips button{border:1px solid var(--line);background:#fff;padding:9px 18px;font:inherit;font-size:14px;cursor:pointer;color:var(--text);border-radius:999px}
.chips button[aria-pressed="true"]{background:var(--esp);color:#fff;border-color:var(--esp)}
.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:26px 20px}
.p{position:relative}
.p figure{margin:0;position:relative;overflow:hidden;background:var(--sand-2);aspect-ratio:3/4}
.p img{width:100%;height:100%;object-fit:cover;transition:transform .5s}
.p:hover img{transform:scale(1.04)}
.p .badge{position:absolute;left:12px;top:12px;background:#fff;font-size:12px;padding:3px 10px;letter-spacing:.06em}
.p .badge.sale{background:var(--wine);color:#fff}
.p .add{position:absolute;left:12px;right:12px;bottom:12px;opacity:0;transform:translateY(8px);transition:.25s}
.p:hover .add,.p .add:focus{opacity:1;transform:none}
.p h3{font-family:var(--sans);font-size:15px;font-weight:500;margin:12px 0 2px;color:var(--text)}
.p .pr{font-size:15px}.p .pr s{color:var(--muted);margin-left:6px}
.p .sw{display:flex;gap:6px;margin-top:6px}.p .sw i{width:14px;height:14px;border-radius:50%;border:1px solid var(--line)}
.look{display:grid;grid-template-columns:1.2fr 1fr;background:var(--esp);color:var(--sand)}
.look img{width:100%;height:100%;object-fit:cover;min-height:520px}
.look div{padding:70px 8%;display:flex;flex-direction:column;justify-content:center}
.look h2{color:#fff;font-size:clamp(44px,5.4vw,78px)}.look p{font-size:18px;margin:20px 0 28px;max-width:40ch}
.look .btn{border-color:var(--sand);color:var(--sand);background:transparent;align-self:flex-start}.look .btn:hover{background:var(--sand);color:var(--esp)}
.cats{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.cat{position:relative;overflow:hidden;aspect-ratio:4/5;text-decoration:none}
.cat img{width:100%;height:100%;object-fit:cover}
.cat span{position:absolute;left:0;right:0;bottom:0;padding:24px;background:linear-gradient(transparent,rgba(43,29,22,.75));color:#fff;font-family:var(--serif);font-size:36px}
.rev{background:var(--sand-2)}
.rv-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.rv{background:#fff;padding:28px;margin:0}
.rv .st{letter-spacing:3px;color:var(--wine)}.rv p{font-family:var(--serif);font-size:24px;line-height:1.3;margin:12px 0}.rv cite{font-style:normal;font-size:14px;color:var(--muted)}
.news{text-align:center}
.news h2{font-size:clamp(38px,4.6vw,58px)}.news p{color:var(--muted);max-width:46ch;margin:14px auto 24px}
.news form{display:flex;max-width:480px;margin:0 auto;border:1px solid var(--esp)}
.news input{flex:1;border:0;padding:14px 16px;font:inherit;min-width:0}.news input:focus{outline:none}
footer{background:var(--esp);color:#BFB2A6;padding:60px 0 28px;font-size:14px}
.foot{display:grid;grid-template-columns:1.5fr repeat(3,1fr);gap:30px;margin-bottom:36px}
footer .logo{color:var(--sand)}footer h3{font-family:var(--sans);font-size:14px;letter-spacing:.1em;color:#fff;margin-bottom:12px}
footer ul{list-style:none;padding:0;margin:0}footer li{margin-bottom:8px}footer a{text-decoration:none}footer a:hover{color:#fff}
.legal{border-top:1px solid #4A3A30;padding-top:18px;display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}
.drawer{position:fixed;top:0;right:0;bottom:0;width:min(420px,100%);background:#fff;z-index:60;transform:translateX(100%);transition:transform .3s;display:flex;flex-direction:column;box-shadow:-20px 0 40px rgba(0,0,0,.15)}
.drawer.open{transform:none}
.dr-h{display:flex;justify-content:space-between;align-items:center;padding:20px 24px;border-bottom:1px solid var(--line)}
.dr-h h2{font-size:30px}.dr-h button{background:none;border:0;font-size:26px;cursor:pointer}
.dr-items{flex:1;overflow:auto;padding:10px 24px}
.ci{display:grid;grid-template-columns:70px 1fr auto;gap:14px;padding:14px 0;border-bottom:1px solid var(--line);align-items:center}
.ci img{width:70px;height:90px;object-fit:cover}.ci b{font-weight:500;display:block}.ci small{color:var(--muted)}
.ci .q{display:flex;align-items:center;gap:8px;margin-top:6px}.ci .q button{width:26px;height:26px;border:1px solid var(--line);background:#fff;cursor:pointer}
.ci .rm{background:none;border:0;color:var(--muted);text-decoration:underline;cursor:pointer;font:inherit;font-size:13px}
.dr-f{padding:20px 24px;border-top:1px solid var(--line)}
.dr-f .sub{display:flex;justify-content:space-between;font-size:18px;margin-bottom:14px}
.dr-f .btn{width:100%}
.empty{color:var(--muted);text-align:center;padding:60px 0}
.scrim{position:fixed;inset:0;background:rgba(43,29,22,.4);z-index:55;opacity:0;pointer-events:none;transition:opacity .3s}.scrim.on{opacity:1;pointer-events:auto}
@media (max-width:1000px){.nav{grid-template-columns:auto 1fr auto}.menu{display:none}.burger{display:block}.logo{text-align:center}
.menu.open{display:flex;flex-direction:column;position:absolute;top:76px;left:0;right:0;background:#fff;padding:20px 24px;border-bottom:1px solid var(--line);gap:14px}
.hero,.look{grid-template-columns:1fr}.hero-img{min-height:420px}.grid{grid-template-columns:repeat(2,1fr)}.perks{grid-template-columns:1fr 1fr}.perks div:nth-child(2){border-right:0}.cats,.rv-grid{grid-template-columns:1fr 1fr}.foot{grid-template-columns:1fr 1fr}.p .add{opacity:1;transform:none;position:static;margin-top:8px;width:100%}}
@media (max-width:560px){section{padding:64px 0}.cats,.rv-grid,.perks{grid-template-columns:1fr}.perks div{border-right:0;border-bottom:1px solid var(--line)}.grid{gap:18px 12px}.icons .lbl{display:none}}

