const P=[["Chunky wool jumper","Knitwear",148,null,"1434389677669-e08b4cac3105","New",["#EFE6D8","#6E1E2C"]],["Cropped bomber jacket","Outerwear",220,null,"1591047139829-d91aecb6caea","",["#C07B55","#2B1D16"]],["Organic cotton tee","Tops",38,null,"1521572163474-6864f9cf17ab","",["#fff","#2B1D16","#8A9A7B"]],["Wide-leg jogger","Trousers",92,120,"1515886657613-9f3515b0c78f","Sale",["#E8B928","#2B1D16"]],["Linen shirt","Tops",86,null,"1490481651871-ab68de25d43d","",["#F4EFE8","#9FB4C7"]],["Double-breasted coat","Outerwear",340,null,"1483985988355-763728e1935b","New",["#6E1E2C","#2B1D16"]],["Striped palazzo trousers","Trousers",110,null,"1509631179647-0177331693ae","",["#2B1D16"]],["Relaxed overshirt","Outerwear",145,180,"1445205170230-053b83016050","Sale",["#D9CBB8","#5A4A3C"]]];
const bag={};const $=id=>document.getElementById(id);const fm=n=>'$'+n.toFixed(0);
function grid(c){$('grid').innerHTML=P.map((p,i)=>[p,i]).filter(([p])=>c==='all'||p[1]===c).map(([p,i])=>`<article class="p"><figure><img src="https://images.unsplash.com/photo-${p[4]}?w=600&h=800&q=75&auto=format&fit=crop" alt="${p[0]}" width="600" height="800" loading="lazy">${p[5]?`<span class="badge ${p[5]==='Sale'?'sale':''}">${p[5]}</span>`:''}<button class="btn btn-dark add" type="button" data-i="${i}">Add to bag</button></figure><h3>${p[0]}</h3><div class="pr">${fm(p[2])}${p[3]?`<s>${fm(p[3])}</s>`:''}</div><div class="sw" aria-label="Colours">${p[6].map(c=>`<i style="background:${c}"></i>`).join('')}</div></article>`).join('')}
document.querySelectorAll('#chips button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('#chips button').forEach(x=>x.setAttribute('aria-pressed',x===b));grid(b.dataset.c)}));grid('all');
function render(){const ids=Object.keys(bag),tot=ids.reduce((a,i)=>a+P[i][2]*bag[i],0),n=ids.reduce((a,i)=>a+bag[i],0);
$('bagCount').textContent=n;$('subtotal').textContent=fm(tot);
$('items').innerHTML=ids.length?ids.map(i=>`<div class="ci"><img src="https://images.unsplash.com/photo-${P[i][4]}?w=140&h=180&q=70&auto=format&fit=crop" alt="" width="70" height="90"><div><b>${P[i][0]}</b><small>${fm(P[i][2])}</small><div class="q"><button type="button" data-q="${i}" data-d="-1" aria-label="One less">−</button><span>${bag[i]}</span><button type="button" data-q="${i}" data-d="1" aria-label="One more">+</button></div></div><button class="rm" type="button" data-rm="${i}">Remove</button></div>`).join(''):'<p class="empty">Your bag is empty.</p>';
const left=150-tot;$('shipmsg').textContent=tot===0?'Free delivery on orders over $150':left>0?`You're ${fm(left)} away from free delivery`:'You have free delivery';$('shipbar').style.width=Math.min(100,tot/150*100)+'%'}
function open(o){$('drawer').classList.toggle('open',o);$('scrim').classList.toggle('on',o);$('drawer').setAttribute('aria-hidden',!o);if(o)$('closeBag').focus()}
$('grid').addEventListener('click',e=>{const b=e.target.closest('[data-i]');if(!b)return;bag[b.dataset.i]=(bag[b.dataset.i]||0)+1;render();open(true)});
$('items').addEventListener('click',e=>{const q=e.target.closest('[data-q]'),r=e.target.closest('[data-rm]');if(q){bag[q.dataset.q]+= +q.dataset.d;if(bag[q.dataset.q]<=0)delete bag[q.dataset.q]}if(r)delete bag[r.dataset.rm];render()});
$('openBag').addEventListener('click',()=>open(true));$('closeBag').addEventListener('click',()=>open(false));$('scrim').addEventListener('click',()=>open(false));
document.addEventListener('keydown',e=>{if(e.key==='Escape')open(false)});render();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
